CREATE SECRET my_sqlite (TYPE adbc, SCOPE 'sqlite://docs', DRIVER 'sqlite', URI ':memory:');
SET VARIABLE conn = (SELECT adbc_connect({'secret': 'my_sqlite'}));
SELECT * FROM adbc_scan(getvariable('conn')::BIGINT, 'SELECT 1 AS id', columns := {'id': 'BIGINT'});
CALL adbc_disconnect(getvariable('conn')::BIGINT);
DROP SECRET my_sqlite;

CREATE SECRET scoped_sqlite (TYPE adbc, SCOPE 'sqlite://docs', DRIVER 'sqlite', URI ':memory:');
SET VARIABLE conn = (SELECT adbc_connect({'uri': 'sqlite://docs'}));
SELECT * FROM adbc_scan(getvariable('conn')::BIGINT, 'SELECT 1 AS id', columns := {'id': 'BIGINT'});
CALL adbc_disconnect(getvariable('conn')::BIGINT);
DROP SECRET scoped_sqlite;
